import React, { useEffect, useRef, useState } from 'react';
import * as tf from '@tensorflow/tfjs';
import * as faceDetection from '@tensorflow-models/face-detection';
import './App.css';

function App() {
  const videoRef = useRef(null);
  const [ballPosition, setBallPosition] = useState(50);
  const [detector, setDetector] = useState(null);
  const [error, setError] = useState(null);
  const [debugInfo, setDebugInfo] = useState('Initializing...');
  const [logs, setLogs] = useState([]);

  // Custom logging function
  const addLog = (message) => {
    console.log(message);
    setLogs(prev => [...prev, `${new Date().toLocaleTimeString()}: ${message}`].slice(-20));
  };

  // Initialize face detector
  useEffect(() => {
    const initializeDetector = async () => {
      try {
        addLog('Loading TensorFlow...');
        await tf.ready();
        
        addLog('Creating detector...');
        const model = faceDetection.SupportedModels.MediaPipeFaceDetector;
        const detector = await faceDetection.createDetector(model, {
          runtime: 'tfjs',
          refineLandmarks: true,
          maxFaces: 1,
        });
        
        addLog('Detector created successfully');
        setDetector(detector);
        startVideo();
      } catch (err) {
        const errorMsg = `Initialization error: ${err.message}`;
        console.error(errorMsg);
        setError(errorMsg);
        addLog(errorMsg);
      }
    };

    initializeDetector();
  }, []);

  // Start video stream
  const startVideo = async () => {
    try {
      addLog('Requesting camera access...');
      const constraints = {
        video: {
          facingMode: 'user',
          width: { ideal: window.innerWidth },
          height: { ideal: window.innerHeight },
        }
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        addLog('Camera started successfully');
      }
    } catch (err) {
      const errorMsg = `Camera error: ${err.message}`;
      console.error(errorMsg);
      setError(errorMsg);
      addLog(errorMsg);
    }
  };

  // Handle face detection
  useEffect(() => {
    if (!detector || !videoRef.current) {
      addLog('Waiting for detector and video...');
      return;
    }

    let animationFrameId;
    let lastBallUpdate = 0;
    let frameCount = 0;
    
    const detectFaces = async () => {
      try {
        if (videoRef.current.readyState === 4) {
          frameCount++;
          if (frameCount % 30 === 0) {
            addLog('Detecting faces...');
          }

          const faces = await detector.estimateFaces(videoRef.current, {
            flipHorizontal: false
          });
          
          if (faces.length > 0) {
            if (frameCount % 30 === 0) {
              addLog(`Found ${faces.length} face(s)`);
            }
            
            const leftEyebrow = faces[0].keypoints.find(k => k.name === 'leftEyebrowUpper');
            const rightEyebrow = faces[0].keypoints.find(k => k.name === 'rightEyebrowUpper');
            const leftEye = faces[0].keypoints.find(k => k.name === 'leftEye');
            const rightEye = faces[0].keypoints.find(k => k.name === 'rightEye');

            if (leftEyebrow && rightEyebrow && leftEye && rightEye) {
              const leftDistance = Math.abs(leftEyebrow.y - leftEye.y);
              const rightDistance = Math.abs(rightEyebrow.y - rightEye.y);
              const avgDistance = (leftDistance + rightDistance) / 2;

              if (frameCount % 30 === 0) {
                addLog(`Eyebrow distance: ${avgDistance.toFixed(2)}`);
              }

              const now = Date.now();
              if (now - lastBallUpdate > 50) {
                if (avgDistance > 15) {
                  setBallPosition(prev => Math.max(0, prev - 8));
                  if (frameCount % 30 === 0) addLog('Eyebrows raised!');
                } else {
                  setBallPosition(prev => Math.min(400, prev + 4));
                }
                lastBallUpdate = now;
              }
            } else {
              if (frameCount % 30 === 0) addLog('Could not find facial landmarks');
            }
          } else {
            if (frameCount % 30 === 0) addLog('No faces detected');
          }
        }
        
        animationFrameId = requestAnimationFrame(detectFaces);
      } catch (err) {
        const errorMsg = `Detection error: ${err.message}`;
        console.error(errorMsg);
        setError(errorMsg);
        addLog(errorMsg);
      }
    };

    detectFaces();

    return () => {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
      }
    };
  }, [detector]);

  return (
    <div className="App">
      <h1>Eyebrow Ball Game</h1>
      <p>Raise your eyebrows to move the ball up!</p>
      
      {error && <div className="error-message">{error}</div>}
      <div className="debug-info">{debugInfo}</div>
      
      <div className="game-container">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          className="video-feed"
        />
        <div 
          className="ball"
          style={{ 
            bottom: `${ballPosition}px`,
            height: '30px',
            backgroundColor: '#61dafb',
            borderRadius: '50%'
          }}
        />
      </div>

      <div className="logs-container">
        {logs.map((log, index) => (
          <div key={index} className="log-entry">{log}</div>
        ))}
      </div>
    </div>
  );
}

export default App; 